# generated by tools/ail2py.py from binary_records_main.ail; edit the .ail until onelang s16
from binary_cursor import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

# Extract matching payloads after validating every record in the input.
def main() -> int:
    if len(sys.argv) != 4:
        print('usage: binary_records input-path output-path kind', file=sys.stderr)
        return 2
    if sys.argv[1] == sys.argv[2]:
        print('input and output paths must differ', file=sys.stderr)
        return 2
    try:
        # ASCII decimal, with an optional sign; check before each multiplication.
        wanted = 0
        position = 0
        negative = False
        digits = False
        for c in sys.argv[3]:
            if position == 0 and (c == '+' or c == '-'):
                negative = c == '-'
            else:
                digit = ord(c) - 48
                if digit < 0 or digit > 9:
                    raise ValueError
                if wanted > 6553 or (wanted == 6553 and digit > 5):
                    raise ValueError
                wanted = wanted * 10 + digit
                digits = True
            position += 1
        if not digits or (negative and wanted != 0):
            raise ValueError
        data = read_bytes(sys.argv[1])
        if file_paths_same(sys.argv[1], sys.argv[2]):
            raise ValueError
        cursor = BinaryCursor(data, 0)
        if cursor.take(4) != b'AILR':
            raise ValueError
        payloads = [b'']
        while cursor.remaining() > 0:
            kind = cursor.read_u16_be()
            length = cursor.read_u32_le()
            if kind == wanted:
                payloads.append(cursor.take(length))
            else:
                cursor.skip(length)
        write_bytes(sys.argv[2], b''.join(payloads))
        return 0
    except ValueError:
        print('invalid kind or binary record input', file=sys.stderr)
        return 2
    except OSError:
        print('binary record file error', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
